import numpy as np


def construct():
    """Baseline: 26 equal circles on a 6x5 grid. Returns (centers, radii)."""
    cols, rows, n = 6, 5, 26
    r = 0.5 / max(cols, rows)
    centers = []
    for k in range(n):
        i, j = divmod(k, cols)
        centers.append([(j + 0.5) / cols, (i + 0.5) / rows])
    return np.array(centers), np.full(n, r)

import numpy as np

def compute_radii_ordered(centers):
    """
    Given centers (n,2), return radii (n,) or None if infeasible.
    Radii are the maximum non-overlapping values respecting square bounds.
    """
    n = centers.shape[0]
    radii = np.empty(n, dtype=float)
    for i in range(n):
        x, y = centers[i]
        r = min(x, y, 1.0 - x, 1.0 - y)
        for j in range(i):
            dx = centers[i, 0] - centers[j, 0]
            dy = centers[i, 1] - centers[j, 1]
            dist = np.hypot(dx, dy)
            r = min(r, dist - radii[j])
        if r < 0:
            return None
        radii[i] = r
    return radii

def grid_layout_26():
    # A compact 5x6 grid subset (26 centers)
    rows, cols = 5, 6
    centers = []
    for i in range(rows):
        for j in range(cols):
            centers.append([(j + 0.5) / cols, (i + 0.5) / rows])
            if len(centers) == 26:
                break
        if len(centers) == 26:
            break
    return np.array(centers, dtype=float)

def clamp_centers(centers, eps=1e-6):
    return np.clip(centers, eps, 1.0 - eps)

def perturb_centers(centers, scale):
    return centers + np.random.normal(scale=scale, size=centers.shape)

def construct():
    np.random.seed(987654321)
    n = 26
    base_centers = grid_layout_26().copy()

    best_centers = None
    best_radii = None
    best_sum = -np.inf

    # Global search settings
    restarts = 8
    global_steps = 1500

    for rstart in range(restarts):
        if rstart == 0:
            centers = base_centers.copy()
        else:
            # diversified starts by jittering and re-clipping
            centers = perturb_centers(base_centers.copy(), scale=0.15)
            centers = clamp_centers(centers)

        radii = compute_radii_ordered(centers)
        if radii is None:
            # attempt to project toward feasibility by shrinking slightly
            radii = None
            continue
        current_sum = float(np.sum(radii))

        # Local improvement loop: force-guided perturbations with acceptance
        for it in range(global_steps):
            i = np.random.randint(0, n)
            old_center = centers[i].copy()
            # adaptive step: larger early, finer later
            t = max(0.01, 1.0 - (it / global_steps))
            step = 0.08 + 0.25 * t
            centers[i] += np.random.normal(scale=step, size=2)
            centers[i] = np.clip(centers[i], 0.0 + 1e-6, 1.0 - 1e-6)

            r_new = compute_radii_ordered(centers)
            if r_new is not None:
                s_new = float(np.sum(r_new))
                # Accept if improved; sometimes accept equal to escape plateaus
                if s_new >= current_sum or np.random.rand() < 0.01:
                    radii = r_new
                    current_sum = s_new
                    if s_new > best_sum:
                        best_sum = s_new
                        best_centers = centers.copy()
                        best_radii = r_new.copy()
                else:
                    centers[i] = old_center
            else:
                centers[i] = old_center

            # Occasional tightening around best found so far
            if best_centers is not None and it % 300 == 0:
                for _ in range(6):
                    j = np.random.randint(0, n)
                    oldb = best_centers[j].copy()
                    best_centers[j] += np.random.normal(scale=0.03, size=2)
                    best_centers[j] = np.clip(best_centers[j], 0.0 + 1e-6, 1.0 - 1e-6)
                    rb = compute_radii_ordered(best_centers)
                    if rb is not None:
                        srb = float(np.sum(rb))
                        if srb > best_sum:
                            best_sum = srb
                            best_radii = rb.copy()
                        else:
                            best_centers[j] = oldb
                    else:
                        best_centers[j] = oldb

    # If nothing found, fall back to a safe feasible packing
    if best_centers is None:
        best_centers = grid_layout_26()
        best_radii = compute_radii_ordered(best_centers)
        if best_radii is None:
            best_radii = np.full(n, 0.01)
        return best_centers, best_radii

    final_radii = compute_radii_ordered(best_centers)
    if final_radii is None:
        final_radii = best_radii

    return best_centers, final_radii
